import { generateBoard, parseBoardCode, type Board } from './board/deal.ts';

export const MAX_MOVES = 999_999;
export const MAX_ELAPSED_MS = 359_999_999;
export const MISMATCH_MS = 800;

export const SELECTION_KIND = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export type Selection =
  | Readonly<{ kind: typeof SELECTION_KIND.closed }>
  | Readonly<{ kind: typeof SELECTION_KIND.one; index: number }>
  | Readonly<{ kind: typeof SELECTION_KIND.mismatch; first: number; second: number; remainingMs: number }>;

export const CLOSED_SELECTION: Selection = { kind: SELECTION_KIND.closed };
export type GameState = Readonly<{
  board: Board;
  matched: readonly number[];
  selection: Selection;
  moves: number;
  elapsedMs: number;
  started: boolean;
}>;

export function createGame(boardCode: string): GameState | null {
  const parsed = parseBoardCode(boardCode);
  if (parsed === null) return null;
  return { board: generateBoard(parsed), matched: [], selection: CLOSED_SELECTION,
    moves: 0, elapsedMs: 0, started: false };
}
import { MAX_ELAPSED_MS, MAX_MOVES, MISMATCH_MS, SELECTION_KIND, CLOSED_SELECTION,
  type GameState } from './state.ts';

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

function isIndex(state: GameState, index: number): boolean {
  return Number.isInteger(index) && index >= 0 && index < state.board.deck.length;
}

function isMatched(state: GameState, index: number): boolean {
  return state.matched.includes(index);
}

export function activateCard(state: GameState, index: number): GameState {
  if (!isIndex(state, index) || isWon(state) || state.selection.kind === SELECTION_KIND.mismatch ||
      isMatched(state, index)) return state;
  if (state.selection.kind === SELECTION_KIND.closed) {
    return { ...state, selection: { kind: SELECTION_KIND.one, index }, started: true };
  }
  if (state.selection.index === index) return state;
  const moves = Math.min(MAX_MOVES, state.moves + 1);
  const first = state.selection.index;
  if (state.board.deck[first] === state.board.deck[index]) {
    return { ...state, matched: [...state.matched, first, index], selection: CLOSED_SELECTION, moves };
  }
  return { ...state, selection: { kind: SELECTION_KIND.mismatch, first, second: index,
    remainingMs: MISMATCH_MS }, moves };
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) return state;
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  if (state.selection.kind !== SELECTION_KIND.mismatch) return { ...state, elapsedMs };
  const remainingMs = state.selection.remainingMs - milliseconds;
  if (remainingMs <= 0) return { ...state, elapsedMs, selection: CLOSED_SELECTION };
  return { ...state, elapsedMs, selection: { ...state.selection, remainingMs } };
}
import { createGame } from './state.ts';
import { isWon } from './transitions.ts';
import { SELECTION_KIND, MAX_ELAPSED_MS, MAX_MOVES, type GameState, type Selection } from './state.ts';

const SNAPSHOT_LIMIT = 65_536;
type Snapshot = Readonly<{ version: 1; boardCode: string; matched: readonly number[];
  selection: Selection; moves: number; elapsedMs: number; started: boolean }>;
type UnknownRecord = Record<string, unknown>;

function record(value: unknown): value is UnknownRecord {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function hasKeys(value: UnknownRecord, keys: readonly string[]): boolean {
  return Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key));
}

function safeInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

function decodeSelection(value: unknown, state: GameState, matched: ReadonlySet<number>): Selection | null {
  if (!record(value) || typeof value.kind !== 'string') return null;
  if (value.kind === SELECTION_KIND.closed) return hasKeys(value, ['kind']) ? { kind: 'closed' } : null;
  if (value.kind === SELECTION_KIND.one) {
    if (!hasKeys(value, ['kind', 'index']) || !safeInteger(value.index) ||
        value.index >= state.board.deck.length || matched.has(value.index)) return null;
    return { kind: 'one', index: value.index };
  }
  if (value.kind !== SELECTION_KIND.mismatch || !hasKeys(value, ['kind', 'first', 'second', 'remainingMs']) ||
      !safeInteger(value.first) || !safeInteger(value.second) || !safeInteger(value.remainingMs) ||
      value.first >= state.board.deck.length || value.second >= state.board.deck.length ||
      value.first === value.second || matched.has(value.first) || matched.has(value.second) ||
      state.board.deck[value.first] === state.board.deck[value.second] || value.remainingMs < 1 || value.remainingMs > 800) return null;
  return { kind: 'mismatch', first: value.first, second: value.second, remainingMs: value.remainingMs };
}

function decodeObject(value: unknown): GameState | null {
  if (!record(value) || !hasKeys(value, ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started']) ||
      value.version !== 1 || typeof value.boardCode !== 'string' || !Array.isArray(value.matched) ||
      !safeInteger(value.moves) || value.moves > MAX_MOVES || !safeInteger(value.elapsedMs) ||
      value.elapsedMs > MAX_ELAPSED_MS || typeof value.started !== 'boolean') return null;
  const state = createGame(value.boardCode);
  if (state === null) return null;
  const matched = new Set<number>();
  for (const index of value.matched) {
    if (!safeInteger(index) || index >= state.board.deck.length || matched.has(index)) return null;
    matched.add(index);
  }
  for (const face of new Set(state.board.deck)) {
    const faceMatches = state.board.deck.flatMap((value, index) => value === face && matched.has(index) ? [index] : []);
    if (faceMatches.length !== 0 && faceMatches.length !== 2) return null;
  }
  const selection = decodeSelection(value.selection, state, matched);
  if (selection === null || (isWon({ ...state, matched: [...matched] }) && selection.kind !== 'closed')) return null;
  const pairs = matched.size / 2;
  const requiredMoves = pairs + (selection.kind === 'mismatch' ? 1 : 0);
  if (value.moves < requiredMoves) return null;
  if (!value.started && (value.moves !== 0 || value.elapsedMs !== 0 || matched.size !== 0 || selection.kind !== 'closed')) return null;
  if (value.started && value.moves === 0 && selection.kind !== 'one') return null;
  return { ...state, matched: [...matched], selection, moves: value.moves, elapsedMs: value.elapsedMs, started: value.started };
}

export function encodeSnapshot(state: GameState): string {
  const selection: Selection = state.selection.kind === 'mismatch'
    ? { ...state.selection, remainingMs: Math.max(1, Math.ceil(state.selection.remainingMs)) } : state.selection;
  const snapshot: Snapshot = { version: 1, boardCode: state.board.boardCode, matched: state.matched,
    selection, moves: state.moves, elapsedMs: Math.floor(state.elapsedMs), started: state.started };
  return JSON.stringify(snapshot, null, 2);
}

export function decodeSnapshot(text: string): GameState | null {
  if (new TextEncoder().encode(text).length > SNAPSHOT_LIMIT) return null;
  try { return decodeObject(JSON.parse(text) as unknown); } catch { return null; }
}
import { createGame } from './state.ts';
import { activateCard, advanceGame } from './transitions.ts';
import type { GameState } from './state.ts';

const REPLAY_LIMIT = 1_048_576;
const ACTION_LIMIT = 10_000;
type ReplayAction = Readonly<{ atMs: number; index: number }>;
type Replay = Readonly<{ version: 1; boardCode: string; actions: readonly ReplayAction[]; endMs: number }>;
type UnknownRecord = Record<string, unknown>;

function record(value: unknown): value is UnknownRecord {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function hasKeys(value: UnknownRecord, keys: readonly string[]): boolean {
  return Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key));
}

function isTime(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

function parseReplay(value: unknown): Replay | null {
  if (!record(value) || !hasKeys(value, ['version', 'boardCode', 'actions', 'endMs']) || value.version !== 1 ||
      typeof value.boardCode !== 'string' || !Array.isArray(value.actions) || value.actions.length > ACTION_LIMIT ||
      !isTime(value.endMs)) return null;
  const actions: ReplayAction[] = [];
  let previous = 0;
  for (const item of value.actions) {
    if (!record(item) || !hasKeys(item, ['atMs', 'index']) || !isTime(item.atMs) || !isTime(item.index) ||
        item.atMs < previous) return null;
    previous = item.atMs;
    actions.push({ atMs: item.atMs, index: item.index });
  }
  if (actions.length > 0 && value.endMs < previous) return null;
  return { version: 1, boardCode: value.boardCode, actions, endMs: value.endMs };
}

export function runReplay(replay: Replay): GameState | null {
  let state = createGame(replay.boardCode);
  if (state === null) return null;
  let previous = 0;
  for (const action of replay.actions) {
    state = advanceGame(state, action.atMs - previous);
    state = activateCard(state, action.index);
    previous = action.atMs;
  }
  return advanceGame(state, replay.endMs - previous);
}

export function replayGame(text: string): GameState | null {
  if (new TextEncoder().encode(text).length > REPLAY_LIMIT) return null;
  try {
    const replay = parseReplay(JSON.parse(text) as unknown);
    return replay === null ? null : runReplay(replay);
  } catch { return null; }
}

export const GRID_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
const MODULUS = 2_147_483_647;
const GENERATOR = 16_807;
const DRAW_RANGE = MODULUS - 1;

export type GridSize = (typeof GRID_SIZES)[number];
export type Board = Readonly<{ boardCode: string; side: GridSize; deck: readonly number[] }>;
export type BoardCode = Readonly<{ boardCode: string; side: GridSize; seed: number }>;

const isGridSize = (value: number): value is GridSize =>
  GRID_SIZES.some((size) => size === value);

export function parseBoardCode(input: string): BoardCode | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(input);
  if (match === null) return null;
  const sideText = match[1];
  const seedText = match[2];
  if (sideText === undefined || seedText === undefined) return null;
  const side = Number(sideText);
  const seed = Number(seedText);
  if (!isGridSize(side) || !Number.isSafeInteger(seed) || seed > DRAW_RANGE) return null;
  return { boardCode: input, side, seed };
}

function nextState(state: number): number {
  return (state * GENERATOR) % MODULUS;
}

function drawIndex(state: number, bound: number): Readonly<{ state: number; index: number }> {
  const limit = Math.floor(DRAW_RANGE / bound) * bound;
  let current = state;
  let value = 0;
  do {
    current = nextState(current);
    value = current - 1;
  } while (value >= limit);
  return { state: current, index: value % bound };
}

export function generateBoard(code: BoardCode): Board {
  const count = code.side * code.side;
  const deck = Array.from({ length: count }, (_, index) => Math.floor(index / 2));
  let state = code.seed;
  for (let index = count - 1; index > 0; index -= 1) {
    const draw = drawIndex(state, index + 1);
    state = draw.state;
    const value = deck[index];
    const other = deck[draw.index];
    if (value !== undefined && other !== undefined) {
      deck[index] = other;
      deck[draw.index] = value;
    }
  }
  return { boardCode: code.boardCode, side: code.side, deck };
}
import { describe, expect, it } from 'vitest';
import { generateBoard, parseBoardCode } from './deal.ts';

describe('version 1 board codes', () => {
  it('matches independent literal decks including the documented example', () => {
    const vectors = [
      ['np1-4-1', [6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3]],
      ['np1-4-2', [2, 0, 1, 4, 7, 4, 5, 6, 5, 7, 2, 0, 3, 1, 3, 6]],
      ['np1-4-2147483646', [6, 7, 2, 4, 5, 0, 3, 1, 0, 7, 5, 4, 6, 2, 1, 3]],
    ] as const;
    for (const [code, deck] of vectors) {
      const parsed = parseBoardCode(code);
      expect(parsed).not.toBeNull();
      if (parsed !== null) expect(generateBoard(parsed).deck).toEqual(deck);
    }
  });

  it('supports each size with exactly two of every face', () => {
    for (const side of [4, 6, 8, 10, 12, 14, 16]) {
      const parsed = parseBoardCode(`np1-${side}-1`);
      expect(parsed).not.toBeNull();
      if (parsed !== null) {
        const deck = generateBoard(parsed).deck;
        expect(deck).toHaveLength(side * side);
        expect(new Set(deck).size).toBe(side * side / 2);
        for (const face of new Set(deck)) expect(deck.filter((card) => card === face)).toHaveLength(2);
      }
    }
  });

  it('rejects whitespace, leading zeroes, unsupported sides and out of range seeds', () => {
    for (const code of [' np1-4-1', 'np1-4-1 ', 'np1-04-1', 'np1-4-0', 'np1-4-01',
      'np1-4-2147483647', 'np1-5-1', 'np2-4-1']) expect(parseBoardCode(code)).toBeNull();
  });
});
import { readFile } from 'node:fs/promises';
import { encodeSnapshot } from '../game/snapshot.ts';
import { replayGame } from '../game/replay.ts';

async function main(): Promise<void> {
  const path = process.argv[2];
  if (process.argv.length !== 3 || path === undefined) {
    process.stderr.write('Usage: npm run --silent replay -- PATH\n');
    process.exitCode = 1;
    return;
  }
  try {
    const text = await readFile(path, 'utf8');
    const state = replayGame(text);
    if (state === null) {
      process.stderr.write('Invalid replay.\n');
      process.exitCode = 1;
      return;
    }
    process.stdout.write(`${encodeSnapshot(state)}\n`);
  } catch {
    process.stderr.write('Invalid replay file.\n');
    process.exitCode = 1;
  }
}

await main();
