    if (result === 'invalid') {
      const status = 'Invalid snapshot.';
      setLoadStatus(status);
      announce(status);
      return result;
    }
    const status = result === 'loaded'
      ? 'Loaded snapshot. Select Resume to continue.' : 'Loaded completed snapshot.';
    setLoadStatus(status);
    announce(status);
    setCelebrating(false);
    return result;
  }

