.game-heading p { margin: 0; color: #B8BDD2; font-size: 14px; }
.game-status { display: flex; flex-wrap: wrap; gap: 8px 24px; margin-block: 24px 16px; }
.game-status p { margin: 0; font-size: 14px; font-variant-numeric: tabular-nums; }
.paused-note { margin: 0 0 12px; color: #B8BDD2; font-size: 14px; }
.completion-banner { margin: 0 0 16px; padding: 12px 16px; border: 1px solid #8BEA7D; border-radius: 8px; background: #141827; }
.completion-banner h2 { margin: 0; font-size: 20px; line-height: 28px; }
.completion-banner p { margin: 4px 0 0; color: #B8BDD2; font-size: 14px; }
.completion-banner--pulse { animation: win-pulse 600ms ease-out 1 both; }
@keyframes win-pulse {
  0% { transform: scale(1); box-shadow: 0 0 0 0 #8BEA7D; }
  45% { transform: scale(1.015); box-shadow: 0 0 16px 2px #8BEA7D; }
  100% { transform: scale(1); box-shadow: 0 0 0 0 #8BEA7D; }
}
