.game-card.is-revealed { background: #111625; }
.game-card.is-matched { background: #111625; border-color: #8BEA7D; }
.card-back-mark { display: block; width: 100%; height: 100%; }
.card-back-mark path { fill: #757C9A; opacity: .64; }
