import { expect, test } from '@playwright/test';
import { loadBoard, pairsFor } from './helpers.ts';

async function completeKnownBoard(page: import('@playwright/test').Page): Promise<void> {
  await loadBoard(page, 'np1-4-1');
  for (const [first, second] of pairsFor('np1-4-1').values()) {
    await page.locator('.game-card').nth(first).dispatchEvent('click');
    await page.locator('.game-card').nth(second).dispatchEvent('click');
  }
}

test('normal completion pulses once for600ms then leaves a static banner', async ({ page }) => {
  await page.goto('/');
  await completeKnownBoard(page);
  const banner = page.locator('.completion-banner');
  await expect(banner).toHaveClass(/completion-banner--pulse/);
  await expect(banner).toHaveCSS('animation-duration', '0.6s');
  await expect(banner).toHaveCSS('animation-iteration-count', '1');
  await expect.poll(() => banner.evaluate((element) => element.getAnimations()[0]?.playState ?? 'none'))
    .toBe('finished');
  await expect(banner).toHaveCSS('transform', 'matrix(1, 0, 0, 1, 0, 0)');
});

test('reduced motion completes with an immediately static banner and card borders', async ({ page }) => {
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.goto('/');
  await completeKnownBoard(page);
  await expect(page.locator('.completion-banner')).toHaveClass(/completion-banner--pulse/);
  await expect(page.locator('.completion-banner')).toHaveCSS('animation-name', 'none');
  await expect(page.locator('.game-card')).toHaveCSS('transition-duration', '0s');
});
import { spawnSync } from 'node:child_process';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { decodeSnapshot } from '../game/snapshot.ts';

const validReplay = JSON.stringify({ version: 1, boardCode: 'np1-4-1',
  actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 11 }], endMs: 800 });

function runReplayCommand(path?: string) {
  const args = ['run', '--silent', 'replay', '--'];
  if (path !== undefined) args.push(path);
  return spawnSync('npm', args, { encoding: 'utf8', timeout: 15_000 });
}

describe('documented replay command', () => {
  it('prints only valid snapshot JSON and reports invalid or missing inputs on stderr', async () => {
    const directory = await mkdtemp(join(tmpdir(), 'neon-pairs-replay-'));
    try {
      const validPath = join(directory, 'valid.json');
      const invalidPath = join(directory, 'invalid.json');
      await writeFile(validPath, validReplay, 'utf8');
      await writeFile(invalidPath, '{"version":1,"boardCode":"np1-4-1","actions":[{"atMs":0,"index":20}],"endMs":0}', 'utf8');
      const valid = runReplayCommand(validPath);
      expect(valid.status).toBe(0);
      expect(valid.stderr).toBe('');
      expect(valid.stdout.endsWith('\n')).toBe(true);
      const state = decodeSnapshot(valid.stdout.trim());
      expect(state?.matched).toEqual([0, 11]);
      expect(state?.moves).toBe(1);
      expect(state?.elapsedMs).toBe(800);

      for (const result of [runReplayCommand(invalidPath), runReplayCommand(join(directory, 'missing.json')),
        runReplayCommand()]) {
        expect(result.status).not.toBe(0);
        expect(result.stdout).toBe('');
        expect(result.stderr.length).toBeGreaterThan(0);
      }
    } finally {
      await rm(directory, { recursive: true, force: true });
    }
  });
});
import { describe, expect, it } from 'vitest';
import { generateBoard, parseBoardCode } from './deal.ts';

describe('version 1 board codes', () => {
  it('matches independent literal decks including the documented example', () => {
    const vectors = [
      ['np1-4-1', [6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3]],
      ['np1-4-2', [2, 0, 1, 4, 7, 4, 5, 6, 5, 7, 2, 0, 3, 1, 3, 6]],
      ['np1-4-2147483646', [6, 7, 2, 4, 5, 0, 3, 1, 0, 7, 5, 4, 6, 2, 1, 3]],
      ['np1-4-739806647', [6, 7, 2, 4, 5, 0, 3, 1, 0, 7, 5, 4, 6, 2, 1, 3]],
    ] as const;
    for (const [code, deck] of vectors) {
      const parsed = parseBoardCode(code);
      expect(parsed).not.toBeNull();
      if (parsed !== null) expect(generateBoard(parsed).deck).toEqual(deck);
    }
  });

  it('supports each size with exactly two of every face', () => {
    for (const side of [4, 6, 8, 10, 12, 14, 16]) {
      const parsed = parseBoardCode(`np1-${side}-1`);
      expect(parsed).not.toBeNull();
      if (parsed !== null) {
        const deck = generateBoard(parsed).deck;
        expect(deck).toHaveLength(side * side);
        expect(new Set(deck).size).toBe(side * side / 2);
        for (const face of new Set(deck)) expect(deck.filter((card) => card === face)).toHaveLength(2);
      }
    }
  });

  it('rejects whitespace, leading zeroes, unsupported sides and out of range seeds', () => {
    for (const code of [' np1-4-1', 'np1-4-1 ', 'np1-4-1\n', 'np1-4-1\r', 'np1-04-1', 'np1-4-0', 'np1-4-01',
      'np1-4-2147483647', 'np1-5-1', 'np2-4-1']) expect(parseBoardCode(code)).toBeNull();
  });
});

