text(await tools.exec_command({cmd:"node --input-type=module <<'NODE'
const seeds = [1,2,2147483646];
for (const seed of seeds) {
  const n=4, q=2147483646n, modulus=2147483647n;
  let state=BigInt(seed);
  const next=()=>state=(state*16807n)%modulus;
  const deck=Array.from({length:n*n},(_,i)=>Math.floor(i/2));
  for(let i=deck.length-1;i>0;i--){
    const b=BigInt(i+1),limit=(q/b)*b;
    let x;
    do {x=next()-1n;} while(x>=limit);
