import './Card.css';

type CardProps = Readonly<{
  index: number;
  side: number;
  faceId: number | null;
  matched: boolean;
  unavailable: boolean;
  tabIndex: 0 | -1;
  buttonRef: (button: HTMLButtonElement | null) => void;
  onFocus: () => void;
  onKeyDown: (event: React.KeyboardEvent<HTMLButtonElement>) => void;
  onActivate: () => void;
}>;

export function Card({ index, side, faceId, matched, unavailable, tabIndex, buttonRef, onFocus, onKeyDown, onActivate }: CardProps) {
