    const previous = stateRef.current;
    if (next === previous) return;
    stateRef.current = next;
    setGame(next);
    if (recordWin && !isWon(previous) && isWon(next)) {
      updateSettings(withBest(settingsRef.current, previous.board.side, next.moves));
      activeClockRef.current = false;
    }
  }

  function synchronizeClock(includeHidden = false): void {
    if (!activeClockRef.current || pausedRef.current || (!includeHidden && document.hidden)) return;
    const current = now();
    const delta = Math.max(0, current - lastTimeRef.current);
    lastTimeRef.current = current;
    if (delta > 0) commit(advanceGame(stateRef.current, delta), false);
    if (isWon(stateRef.current)) activeClockRef.current = false;
  }

