import { Face, getFaceName } from './Face.tsx';
import type { KeyboardEvent } from 'react';
import './Card.css';

type CardProps = Readonly<{
  index: number;
  side: number;
  faceId: number | null;
  matched: boolean;
  unavailable: boolean;
  tabIndex: 0 | -1;
