import { chromium } from '@playwright/test';
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ viewport: { width: 360, height: 800 } });
const page = await context.newPage();
const failures = [];
page.on('pageerror', error => failures.push(error.message));
await page.goto('http://127.0.0.1:4173');
await page.getByLabel('Grid size').selectOption('4');
let buttons = page.getByRole('group', { name: '4 by 4 card board' }).getByRole('button');
if (await buttons.count() !== 16) throw new Error('Expected 16 card buttons');
const firstName = await buttons.nth(0).getAttribute('aria-label');
if (firstName !== 'Row 1, column 1, closed') throw new Error(`Unexpected hidden name: ${firstName}`);
if (await buttons.nth(0).locator('svg.face-art').count() !== 0) throw new Error('Hidden face art is mounted');
