const width = await page.evaluate(() => ({ innerWidth: window.innerWidth, documentWidth: document.documentElement.scrollWidth }));
if (!firstBox || firstBox.width < 44 || width.documentWidth > width.innerWidth) throw new Error(`Bad phone layout: ${JSON.stringify({ firstBox, width })}`);
await page.getByText('Reproduce a game', { exact: true }).click();
await page.getByLabel('Board code').fill('bad');
await page.getByRole('button', { name: 'Load board' }).click();
if (await page.locator('.reproduction-status').innerText() !== 'Invalid board code.') throw new Error('Invalid board error was not visible');
await page.getByLabel('Board code').fill(' np1-4-1 ');
await page.getByRole('button', { name: 'Load board' }).click();
if (await page.locator('.reproduction-status').innerText() !== 'Loaded board.') throw new Error('Valid board load was not visible');
buttons = page.getByRole('group', { name: '4 by 4 card board' }).getByRole('button');
await buttons.nth(0).focus();
await page.keyboard.press('ArrowRight');
if (await page.evaluate(() => document.activeElement?.getAttribute('aria-label')) !== 'Row 1, column 2, closed') throw new Error('ArrowRight did not move focus by one cell');
await buttons.nth(0).click();
if (await page.locator('.game-status').getByText('Moves: 0', { exact: true }).count() !== 1) throw new Error('First reveal unexpectedly counted a move');
const hiddenRemaining = await page.locator('button[aria-label$="closed"]').count();
if (hiddenRemaining !== 15) throw new Error('First reveal not visible');
await page.screenshot({ path: '/tmp/neon-pairs-phone.png', fullPage: true });
if (failures.length) throw new Error(`Browser errors: ${failures.join('; ')}`);
process.stdout.write(JSON.stringify({ firstName, firstCardSize: firstBox, width, hiddenRemaining, errors: failures }) + '\n');
await browser.close();
