import { chromium } from '@playwright/test';
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ viewport: { width: 360, height: 800 } });
const page = await context.newPage();
const faults = [];
page.on('pageerror', error => faults.push(error.message));
await page.clock.install({ time: new Date('2026-11-04T12:00:00Z') });
await page.goto('http://127.0.0.1:4173');
await page.clock.pauseAt(new Date('2026-11-04T12:01:00Z'));
await page.getByText('Reproduce a game', { exact: true }).click();
await page.getByLabel('Board code').fill('np1-4-1');
await page.getByRole('button', { name: 'Load board' }).click();
const board = page.getByRole('group', { name: '4 by 4 card board' });
const cards = board.getByRole('button');
await page.clock.runFor(73);
await cards.nth(0).click();
await cards.nth(1).click();
if ((await cards.nth(0).getAttribute('aria-label'))?.endsWith('closed')) throw new Error('Mismatch did not reveal cards');
await page.clock.runFor(799);
if ((await cards.nth(0).getAttribute('aria-label'))?.endsWith('closed')) throw new Error('Mismatch closed before its 800ms deadline');
await page.clock.runFor(1);
if (await cards.nth(0).getAttribute('aria-label') !== 'Row 1, column 1, closed') throw new Error('Mismatch remained open after the exact 800ms deadline');
const snapshot = JSON.stringify({ version: 1, boardCode: 'np1-4-1', matched: [], selection: { kind: 'mismatch', first: 0, second: 1, remainingMs: 1 }, moves: 1, elapsedMs: 0, started: true });
await page.getByLabel('Snapshot JSON').fill(snapshot);
await page.getByRole('button', { name: 'Load snapshot' }).click();
if (await page.getByRole('button', { name: 'Resume' }).count() !== 1) throw new Error('Unfinished import must show one Resume button');
await cards.nth(1).focus();
await page.keyboard.press('ArrowRight');
const pausedFocus = await page.evaluate(() => document.activeElement?.getAttribute('aria-label'));
if (pausedFocus !== 'Row 1, column 3, closed') throw new Error(`Arrow movement while paused failed: ${pausedFocus}`);
await cards.nth(2).click();
if (await cards.nth(2).getAttribute('aria-label') !== 'Row 1, column 3, closed') throw new Error('Paused card activation was accepted');
await page.getByRole('button', { name: 'Resume' }).click();
const resumeFocus = await page.evaluate(() => document.activeElement?.getAttribute('aria-label'));
if (resumeFocus !== 'Row 1, column 3, closed') throw new Error(`Resume did not focus the remembered card first: ${resumeFocus}`);
await page.clock.runFor(1);
if (await cards.nth(0).getAttribute('aria-label') !== 'Row 1, column 1, closed') throw new Error('Imported 1ms mismatch failed to resolve after Resume');
if (await page.getByRole('button', { name: 'Resume' }).count() !== 0) throw new Error('Resume must disappear after activation');
if (faults.length) throw new Error(`Browser errors: ${faults.join('; ')}`);
