import { describe, expect, it } from 'vitest';
import { replayGame } from './replay.ts';
import { isWon } from './transitions.ts';

const replay = (actions: readonly object[], endMs: number) => JSON.stringify({
  version: 1, boardCode: 'np1-4-1', actions, endMs,
});

describe('version 1 timed replays', () => {
  it('matches the documented replay and starts elapsed time on first reveal', () => {
    const state = replayGame(replay([{ atMs: 0, index: 0 }, { atMs: 0, index: 11 }], 800));
    expect(state).not.toBeNull();
    expect(state?.matched).toEqual([0, 11]);
    expect(state?.moves).toBe(1);
    expect(state?.elapsedMs).toBe(800);
    const delayed = replayGame(replay([{ atMs: 500, index: 0 }, { atMs: 700, index: 11 }], 900));
    expect(delayed?.elapsedMs).toBe(400);
  });

  it('resolves a timeout before equal-time actions and preserves equal-time array order', () => {
    const state = replayGame(replay([{ atMs: 0, index: 0 }, { atMs: 0, index: 1 },
      { atMs: 400, index: 2 }, { atMs: 800, index: 2 }], 800));
    expect(state?.moves).toBe(1);
    expect(state?.selection).toEqual({ kind: 'one', index: 2 });
    const simultaneous = replayGame(replay([{ atMs: 0, index: 0 }, { atMs: 0, index: 11 }], 0));
    expect(simultaneous?.matched).toEqual([0, 11]);
  });

  it('stops clock when won and rejects invalid formats and limits', () => {
    const actions: object[] = [];
    const deck = [6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3];
    for (let face = 0; face < 8; face += 1) {
      const pair = deck.flatMap((value, index) => value === face ? [index] : []);
      const first = pair[0];
      const second = pair[1];
      if (first !== undefined && second !== undefined) {
        actions.push({ atMs: face, index: first }, { atMs: face, index: second });
      }
    }
    const win = replayGame(replay(actions, 10_000));
    expect(win).not.toBeNull();
    if (win !== null) { expect(isWon(win)).toBe(true); expect(win.elapsedMs).toBe(7); }
    expect(replayGame(replay([{ atMs: 2, index: 0 }, { atMs: 1, index: 1 }], 2))).toBeNull();
    expect(replayGame(replay([{ atMs: 0, index: 20 }], 0))).toBeNull();
    expect(replayGame('é'.repeat(524_289))).toBeNull();
    expect(replayGame(replay(Array.from({ length: 10_001 }, () => ({ atMs: 0, index: 0 })), 0))).toBeNull();
  });

  it('caps replay elapsed time safely at the game limit', () => {
    const state = replayGame(replay([{ atMs: 0, index: 0 }], 400_000_000));
    expect(state?.elapsedMs).toBe(359_999_999);
  });
});
import { describe, expect, it } from 'vitest';
import { createGame } from './state.ts';
import { activateCard } from './transitions.ts';
import { decodeSnapshot, encodeSnapshot } from './snapshot.ts';

const start = () => {
  const state = createGame('np1-4-1');
  if (state === null) throw new Error('Test board must be valid');
  return state;
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function parseObject(text: string): Record<string, unknown> {
  const parsed: unknown = JSON.parse(text);
  if (!isRecord(parsed)) throw new Error('Expected object');
  return parsed;
}

describe('version 1 snapshots', () => {
  it('round trips closed, one-card and mismatch progress', () => {
    const states = [start(), activateCard(start(), 0),
      activateCard(activateCard(start(), 1), 2)];
    for (const state of states) expect(decodeSnapshot(encodeSnapshot(state))).toEqual(state);
  });

  it('accepts the documented example', () => {
    const sample = '{"version":1,"boardCode":"np1-4-1","matched":[0,11],"selection":{"kind":"mismatch","first":1,"second":2,"remainingMs":300},"moves":2,"elapsedMs":1500,"started":true}';
    expect(decodeSnapshot(sample)?.matched).toEqual([0, 11]);
  });

  it('rejects malformed JSON, oversized UTF-8 and unknown or missing fields', () => {
    expect(decodeSnapshot('{')).toBeNull();
    expect(decodeSnapshot('é'.repeat(32_769))).toBeNull();
    const valid = parseObject(encodeSnapshot(start()));
    expect(decodeSnapshot(JSON.stringify({ ...valid, surprise: true }))).toBeNull();
    const missing = { ...valid };
    delete missing.version;
    expect(decodeSnapshot(JSON.stringify(missing))).toBeNull();
  });

  it('rejects partial pairs, duplicate positions, invalid selections and inconsistent moves', () => {
    const base = parseObject(encodeSnapshot(activateCard(start(), 0)));
    for (const change of [
      { matched: [0] }, { matched: [0, 0] },
      { selection: { kind: 'one', index: 99 } },
      { selection: { kind: 'mismatch', first: 0, second: 11, remainingMs: 800 } },
      { started: false }, { selection: { kind: 'closed' } },
    ]) expect(decodeSnapshot(JSON.stringify({ ...base, ...change }))).toBeNull();
  });

  it('requires a visible card when a started game has zero moves', () => {
    const hiddenStarted = { version: 1, boardCode: 'np1-4-1', matched: [],
      selection: { kind: 'closed' }, moves: 0, elapsedMs: 0, started: true };
    expect(decodeSnapshot(JSON.stringify(hiddenStarted))).toBeNull();
  });
});
import { describe, expect, it } from 'vitest';
import { decodeSettings, withBest, type SavedSettings } from './preferences.ts';

describe('saved browser settings', () => {
  it('validates size and finite capped best scores', () => {
    expect(decodeSettings('{"version":1,"size":6,"bests":{"4":12,"6":null}}')).toEqual({ size: 6, bests: { 4: 12 } });
    for (const text of ['{', '{"version":1,"size":5,"bests":{}}',
      '{"version":1,"size":4,"bests":{},"extra":true}',
    ]) expect(decodeSettings(text)).toBeNull();
    expect(decodeSettings('{"version":1,"size":4,"bests":{"4":1000000}}'))
      .toEqual({ size: 4, bests: {} });
  });

  it('keeps equal or worse move records and replaces a better one', () => {
    const saved: SavedSettings = { size: 4, bests: { 4: 5 } };
    expect(withBest(saved, 4, 5)).toBe(saved);
    expect(withBest(saved, 4, 7)).toBe(saved);
    expect(withBest(saved, 4, 3).bests[4]).toBe(3);
  });
});

